-- ==================================================================
-- PARCHE 12 - COMENTARIOS DE TABLAS Y COLUMNAS DEL MODELO v10
-- ==================================================================
-- Generado por migration/generar_comentarios_sql.py. No editar a mano.
--
-- Escribe el proposito de cada tabla logica y la descripcion de cada
-- columna del modelo v10 en el catalogo del motor (COMMENT ON), para que
-- el diccionario de datos se alimente de la base y no de un archivo
-- paralelo.
--
-- Cobertura:
--   - tablas logicas del modelo v10, sin las particiones;
--   - columnas de esas mismas tablas.
--
-- Queda fuera, a proposito:
--   - las 24 particiones, porque PostgreSQL no hereda comentarios; el
--     diccionario copia la descripcion de la tabla padre al generarse;
--   - el esquema legacy, que se documenta con la curaduria del proyecto.
--
-- Idempotente: COMMENT ON reemplaza el comentario anterior.
-- ==================================================================

-- ---- Proposito de cada tabla --------------------------------

COMMENT ON TABLE agent.cat_detalle_schema IS 'Esquemas JSON versionados que fijan la estructura del detalle de cada corrida de agente, para validar lo que registra la bitácora.';
COMMENT ON TABLE agent.feedback_log IS 'Corrección humana sobre la salida de un agente, con su justificación y el revisor que la emitió, para medir y ajustar su desempeño.';
COMMENT ON TABLE agent.lessons_learned IS 'Lección derivada de un error del agente, con el patrón detectado y un ejemplo, aprobada para incorporarse a sus plantillas de prompt.';
COMMENT ON TABLE agent.llm_call IS 'Registro de cada llamada a un modelo de lenguaje: modelo, versión, tokens, latencia, hash del prompt y veredicto de los guardrails.';
COMMENT ON TABLE agent.llm_call_fragmento IS 'Vínculo entre una llamada al modelo y los fragmentos documentales que recuperó, con su posición y sus puntajes de fusión y reordenamiento.';
COMMENT ON TABLE agent.modelo_registro IS 'Padrón de modelos autorizados, con versión, hash de pesos, destinos permitidos y estado, para saber qué modelo puede operar cada consulta.';
COMMENT ON TABLE agent.plantilla_prompt IS 'Plantilla de prompt versionada por agente, con su prompt de sistema, ejemplos y esquema de salida, para auditar una respuesta contra su origen.';
COMMENT ON TABLE agent.run_log IS 'Bitácora encadenada por hash de las decisiones de cada agente, con confianza, insumos y detalle, para probar que un resultado no fue alterado.';
COMMENT ON TABLE agent.sesion IS 'Sesión de un usuario con el agente, ligada a un plan de análisis; se conserva mientras se migra a la conversación versionada del esquema chat.';
COMMENT ON TABLE agent.sesion_paso IS 'Paso de una sesión con el agente, con su tipo, contenido y momento, como registro lineal previo al esquema de conversación versionada.';
COMMENT ON TABLE agent.synthetic_test_cases IS 'Caso de prueba sintético generado desde un caso semilla, con la variación aplicada, la entrada, el resultado esperado y la exactitud obtenida.';
COMMENT ON TABLE analisis.cat_herramientas IS 'Catálogo de herramientas externas que puede ejecutar un paso de análisis: MAXQDA, ATLAS.ti, NVivo, IRaMuTeQ, R, Excel u otra.';
COMMENT ON TABLE analisis.plan IS 'Plan de análisis dirigido sobre un caso: pregunta, tipo, pauta propuesta, versión y responsables de crearlo y aprobarlo.';
COMMENT ON TABLE analisis.plan_paso IS 'Paso de un plan de análisis con su instrucción, herramienta, entregable esperado, punto de ingesta y dependencia respecto de otro paso.';
COMMENT ON TABLE analisis.punto_ingesta IS 'Catálogo de puntos de ingreso manual de datos, con su esquema de validación y el destino donde se cargan en el modelo.';
COMMENT ON TABLE audit.datos_personales_acceso IS 'Bitácora inmutable de acceso y escritura sobre datos personales de actores, exigida por la Ley 29733: no se corrige, se amplía con una fila nueva.';
COMMENT ON TABLE avisa.raw_ingest IS 'Mensaje crudo recibido por un canal de entrada, con su huella de origen, contenido, versión del extractor y confianza, antes de hacerse registro del modelo.';
COMMENT ON TABLE avisa.raw_ingest_rejected IS 'Mensaje crudo descartado por el canal de ingesta, con el error que motivó el rechazo, para reprocesarlo o explicar por qué no ingresó.';
COMMENT ON TABLE chat.blame IS 'Atribución de cada afirmación a su turno y commit de origen, incluida la herencia cuando el texto proviene de una versión anterior.';
COMMENT ON TABLE chat.blob IS 'Contenido de conversación deduplicado por hash, con recuento de referencias para liberar el espacio cuando deja de usarse.';
COMMENT ON TABLE chat.cherry_pick IS 'Traslado de un commit desde una rama hacia otra, con el resultado de la operación y los conflictos que debieron resolverse.';
COMMENT ON TABLE chat.commit IS 'Versión cerrada de una conversación: árbol de turnos y configuración exacta con que se produjo, es decir modelo, parámetros, librerías y política.';
COMMENT ON TABLE chat.diff IS 'Comparación calculada entre dos versiones de una conversación, con el tipo de diferencia detectada y su detalle.';
COMMENT ON TABLE chat.hook IS 'Regla automática que se ejecuta ante un evento del repositorio de conversación, con su código, lenguaje y orden de aplicación.';
COMMENT ON TABLE chat.merge IS 'Fusión de dos ramas de conversación, con su base común, la estrategia aplicada y los conflictos resueltos.';
COMMENT ON TABLE chat.rama IS 'Rama de un repositorio de conversación: puntero a un commit que permite explorar hipótesis en paralelo y fusionarlas después.';
COMMENT ON TABLE chat.ref IS 'Referencia con nombre sobre un commit, como una rama publicada o una etiqueta, con su mensaje y su fecha de marcado.';
COMMENT ON TABLE chat.reflog IS 'Rastro de los movimientos de las referencias de un repositorio, con el commit anterior y el nuevo, para reconstruir qué cambió y quién lo hizo.';
COMMENT ON TABLE chat.remote IS 'Repositorio remoto con el que se sincroniza una conversación versionada, con su ubicación, credencial y último intercambio.';
COMMENT ON TABLE chat.repositorio IS 'Repositorio de una conversación con IA, por caso, actor, territorio o libre, con su rama por defecto y su nivel de clasificación.';
COMMENT ON TABLE chat.stash IS 'Conjunto de turnos guardados aparte sin confirmar, para retomarlos después en su rama de origen.';
COMMENT ON TABLE chat.turno IS 'Turno de una conversación con su rol, contenido, modelo, agente y consumo, con hash propio para comparar y atribuir afirmaciones.';
COMMENT ON TABLE community.encuestas_percepcion IS 'Encuesta de percepción aplicada en una caleta: satisfacción, confianza institucional, seguridad y servicios, con consentimiento y encuestador.';
COMMENT ON TABLE config.a2_transiciones IS 'Máquina de estados del agente generador de pautas: estado de origen, estado de destino, evento que dispara el cambio y condición de guarda.';
COMMENT ON TABLE config.aplicacion IS 'Aplicación registrada del ecosistema, con su tipo, configuración, modelo y librerías, para reproducir lo que ejecutó cada proceso.';
COMMENT ON TABLE config.guardrail_contract IS 'Contrato de prueba de un guardrail: qué entrada lo dispara, qué salida se espera y qué caso negativo no debe activarlo.';
COMMENT ON TABLE config.libreria IS 'Librería de software registrada con su versión, licencia, dependencias y parámetros por defecto, para fijar el entorno de ejecución.';
COMMENT ON TABLE config.parametro IS 'Parámetro operativo con su valor vigente, unidad y norma de origen, versionado para que un umbral no dependa del código.';
COMMENT ON TABLE config.schema_registry IS 'Registro de versiones de los esquemas de extracción por tipo de registro, con su vigencia, para que un cambio de esquema no rompa el histórico.';
COMMENT ON TABLE consultation.actores IS 'Participación de un actor en un proceso de consulta previa, con el rol que cumple en esa consulta y su vinculación con el padrón general.';
COMMENT ON TABLE consultation.etapas IS 'Etapa de un proceso de consulta previa, con sus fechas de inicio y fin, el documento de evidencia y las observaciones del caso.';
COMMENT ON TABLE consultation.procesos IS 'Proceso de consulta previa asociado a un caso, con el pueblo indígena involucrado, su fase actual y su estado.';
COMMENT ON TABLE consultation.resultados IS 'Resultado o acuerdo alcanzado en un proceso de consulta, con su tipo, descripción, fecha y documento de respaldo.';
COMMENT ON TABLE core.actor_alias IS 'Otros nombres con los que se conoce a un actor —alias, abreviatura, cargo o nombre histórico—, con su fuente y si un analista lo validó.';
COMMENT ON TABLE core.actor_datos_personales IS 'Datos personales del actor cifrados con AES-256 y su HMAC de búsqueda, con base legal y consentimiento, separados del padrón por privacidad.';
COMMENT ON TABLE core.actor_membresia IS 'Pertenencia de una persona a una organización, con el cargo que ejerce y el período de vigencia del vínculo.';
COMMENT ON TABLE core.actores IS 'Sujeto individual o colectivo que participa en la conflictividad —dirigente, gremio, autoridad o empresa— con su tipo, rol, perfil y distrito de referencia.';
COMMENT ON TABLE core.acuerdo_ospa_sni IS 'Acuerdo entre una organización social de pescadores artesanales y una planta, con volumen y precio comprometidos y su grado de cumplimiento.';
COMMENT ON TABLE core.alerta_especies IS 'Especies involucradas en una alerta temprana, como vínculo entre la alerta y el catálogo de especies del sector.';
COMMENT ON TABLE core.alertas_actores IS 'Actores implicados en una alerta temprana, como vínculo entre la alerta y el padrón de actores.';
COMMENT ON TABLE core.alertas_tempranas IS 'Alerta temprana sobre un caso: situación actual, riesgos, acciones sugeridas, nivel, prioridad y plazos de atención y remisión.';
COMMENT ON TABLE core.banco_datos_tratamiento IS 'Registro del banco de datos personales que exige la Ley 29733: finalidad, categorías tratadas, plazo de conservación, nivel de seguridad, oficial responsable, flujo transfronterizo y estado de inscripción ante la autoridad.';
COMMENT ON TABLE core.cambio_normativo IS 'Solicitud de cambio sobre datos normativos, con el antes y el después de la fila, la norma que lo respalda y su aprobación o reversión.';
COMMENT ON TABLE core.capacidad_campo IS 'Horas de campo disponibles de cada usuario en un mes, para planificar la recolección y estimar el esfuerzo de cerrar brechas de información.';
COMMENT ON TABLE core.capacitacion_participantes IS 'Inscripción y culminación de un actor en una capacitación, como vínculo entre la actividad formativa y el padrón de actores.';
COMMENT ON TABLE core.capacitaciones IS 'Actividad de capacitación realizada, con su tipo, modalidad, lugar, fechas, duración, estado y material de respaldo.';
COMMENT ON TABLE core.caso_cronologia IS 'Hecho relevante de la historia de un caso, con su fecha, descripción, tipo, actor involucrado y carácter verificable o crítico.';
COMMENT ON TABLE core.caso_distritos IS 'Distritos alcanzados por un caso, como vínculo entre el expediente y la división territorial distrital.';
COMMENT ON TABLE core.caso_estado_historial IS 'Tramo de vigencia del estado, nivel de conflicto y nivel de riesgo de un caso, con el motivo y el usuario que provocó el cambio.';
COMMENT ON TABLE core.caso_factores IS 'Factores de contexto que inciden en un caso —climático, sanitario, exportador o social— con su período de vigencia.';
COMMENT ON TABLE core.caso_lugares IS 'Lugares vinculados a un caso, como cruce entre el expediente y el registro territorial de lugares.';
COMMENT ON TABLE core.caso_regiones IS 'Regiones alcanzadas por un caso y una marca que indica cuál de ellas se considera la principal.';
COMMENT ON TABLE core.casos IS 'Expediente de conflictividad social: entidad, subsector, temática, niveles de conflicto y riesgo, estado y porcentaje de avance de la intervención.';
COMMENT ON TABLE core.casos_actores IS 'Vínculo de un actor con un caso, con su nivel de influencia y la posición que adopta frente al conflicto.';
COMMENT ON TABLE core.cat_alcances_geograficos IS 'Catálogo de alcances geográficos de un caso o compromiso: norte, centro, sur, oriente o nacional.';
COMMENT ON TABLE core.cat_ciclos_intervencion IS 'Catálogo de ciclos de intervención: prevención, intervención y tratamiento, seguimiento y gestión del conocimiento.';
COMMENT ON TABLE core.cat_clasificacion IS 'Catálogo de niveles de clasificación de la información: público, reservado y confidencial, que gobierna el acceso por fila.';
COMMENT ON TABLE core.cat_especies IS 'Catálogo de especies pesqueras y acuícolas con nombre común, nombre científico, familia, grupo biológico y ámbito.';
COMMENT ON TABLE core.cat_estados_caso IS 'Catálogo de estados del ciclo de vida de un caso: activo, en seguimiento, resuelto o archivado.';
COMMENT ON TABLE core.cat_estados_compromiso IS 'Catálogo de estados de un compromiso, agrupados en abiertos y cerrados, con marca de si son terminales.';
COMMENT ON TABLE core.cat_estados_hito IS 'Catálogo de estados de un hito de compromiso: registrado, en ejecución, paralizado, cumplido o desestimado.';
COMMENT ON TABLE core.cat_estados_integracion IS 'Catálogo de estados del envío hacia un sistema externo: pendiente de aprobación, aprobado, enviado, confirmado o fallido.';
COMMENT ON TABLE core.cat_factores_contexto IS 'Catálogo de factores de contexto que pueden explicar un caso: climático, exportador, geopolítico, sanitario o de vulnerabilidad social.';
COMMENT ON TABLE core.cat_mapeo_estado_externo IS 'Equivalencia entre el estado local de un compromiso y el estado que espera un sistema externo, como SESIGUE.';
COMMENT ON TABLE core.cat_niveles_alerta IS 'Catálogo de niveles de alerta con su plazo de atención y su carácter reactivo o preventivo.';
COMMENT ON TABLE core.cat_niveles_conflicto IS 'Catálogo de niveles de conflictividad social, de la diferencia a la crisis social, con su orden de gravedad.';
COMMENT ON TABLE core.cat_niveles_riesgo IS 'Catálogo de niveles de riesgo del caso —bajo, moderado o alto— con su orden para comparar y escalar.';
COMMENT ON TABLE core.cat_perfiles_actor IS 'Catálogo de perfiles de comportamiento del actor —dialogante, legitimante o disruptivo— según su disposición al diálogo.';
COMMENT ON TABLE core.cat_pip_etapas IS 'Catálogo de etapas del ciclo de inversión pública, numeradas y ordenadas dentro de cada fase del proyecto.';
COMMENT ON TABLE core.cat_pip_fases IS 'Catálogo de fases del ciclo de inversión pública: programación, preinversión, inversión, ejecución y funcionamiento.';
COMMENT ON TABLE core.cat_prioridades_alerta IS 'Catálogo de prioridades de alerta, con su plazo de respuesta: crítica inmediata, urgente, temprana o seguimiento.';
COMMENT ON TABLE core.cat_prioridades_atencion IS 'Catálogo de prioridades de atención de un caso —urgente, moderado o bajo— con su orden de atención.';
COMMENT ON TABLE core.cat_roles_actor IS 'Catálogo de roles del actor en el conflicto: principal, secundario, tercero, proveedor, exportador o inspector.';
COMMENT ON TABLE core.cat_roles_funcionales IS 'Catálogo de roles funcionales del actor en el análisis: decisor, proveedor de evidencia, implementador o articulador territorial.';
COMMENT ON TABLE core.cat_subsectores IS 'Catálogo de subsectores del sector: pesca y acuicultura, MYPE e industria, y gestión y prevención de conflictos.';
COMMENT ON TABLE core.cat_tematicas IS 'Catálogo de temáticas que clasifican el origen del conflicto, de infraestructura a impactos de terceros, con su definición.';
COMMENT ON TABLE core.cat_tipos_actor IS 'Catálogo de tipos de actor: del Estado, de la sociedad civil o privado, más los tipos propios de los módulos sectoriales.';
COMMENT ON TABLE core.cat_tipos_cambio_caso IS 'Catálogo de tipos de cambio de un caso: escalada, desescalada, cierre, reapertura, desestimación o cambio de fase.';
COMMENT ON TABLE core.cat_tipos_capacitacion IS 'Catálogo de tipos de capacitación impartida al público objetivo: taller, curso, charla o asistencia técnica.';
COMMENT ON TABLE core.cat_tipos_documento IS 'Catálogo de tipos de documento, con el anexo de la Guía que lo origina y el esquema esperado de su contenido.';
COMMENT ON TABLE core.cat_tipos_espacio_dialogo IS 'Catálogo de tipos de espacio de diálogo: mesa formalizada, comisión sectorial o multisectorial y grupo de trabajo.';
COMMENT ON TABLE core.cat_tipos_fuente_integracion IS 'Catálogo de fuentes externas con las que se integra el sistema: SESIGUE, IMARPE, OEFA, SUNAT, VUCE, entre otras.';
COMMENT ON TABLE core.cat_tipos_hecho IS 'Catálogo de tipos de hecho que se registran en la cronología de un caso, como bloqueo, comunicado o reunión técnica.';
COMMENT ON TABLE core.cat_tipos_organizacion IS 'Catálogo de formas organizativas: asociación, sindicato, cooperativa, comité, federación o gremio no formalizado.';
COMMENT ON TABLE core.cat_tipos_reunion IS 'Catálogo de tipos de reunión de diálogo: asistencia técnica, preparatoria, ordinaria plenaria u otra.';
COMMENT ON TABLE core.cat_unidades_organicas IS 'Catálogo jerárquico de unidades orgánicas de cada entidad, con siglas y unidad padre, para asignar responsabilidades.';
COMMENT ON TABLE core.compromiso_colaboradores IS 'Actores que colaboran en la ejecución de un compromiso, como vínculo entre el compromiso y el padrón de actores.';
COMMENT ON TABLE core.compromiso_distritos IS 'Distritos donde aplica un compromiso, como vínculo entre el compromiso y la división territorial distrital.';
COMMENT ON TABLE core.compromiso_pip IS 'Proyecto de inversión pública asociado a un compromiso, con su código, monto total, presupuesto y avance de ejecución.';
COMMENT ON TABLE core.compromisos IS 'Acuerdo asumido en una reunión de diálogo, con su acción, responsable, plazo, estado y criterios de verificación del cumplimiento.';
COMMENT ON TABLE core.cronologia_vinculos IS 'Cruce de un hecho de la cronología con la alerta o el documento que lo respalda o lo origina.';
COMMENT ON TABLE core.demandas IS 'Demanda planteada por los actores, desagregada en problema, propuesta y pedido, con su estado de atención y su sustento.';
COMMENT ON TABLE core.demandas_actores IS 'Actores que plantean o respaldan una demanda, con el rol que cumplen en cada una de ellas.';
COMMENT ON TABLE core.demandas_evidencias IS 'Evidencia incorporada a una demanda, con su tipo de fuente, su referencia y el archivo adjunto que la sustenta.';
COMMENT ON TABLE core.derivaciones_alerta IS 'Derivación de una alerta al área competente, con la fecha de envío, el plazo de respuesta y la fecha de atención.';
COMMENT ON TABLE core.distritos IS 'División distrital con su código de ubigeo y su provincia, base de toda desagregación territorial del sistema.';
COMMENT ON TABLE core.documento_actores IS 'Actor mencionado o vinculado a un documento, con el rol que cumple y si es su sujeto principal.';
COMMENT ON TABLE core.documentos IS 'Documento del expediente —reporte, acta, informe, argumentario o relatoría— con su tipo, fecha, resumen y archivo.';
COMMENT ON TABLE core.entidades IS 'Entidad del Estado con la que se relaciona el sistema, con sus siglas, su nivel y su estado.';
COMMENT ON TABLE core.envios_comunicacion IS 'Envío de comunicaciones y oficios, con su canal, remitente, destinatario, documento adjunto y resultado de la entrega.';
COMMENT ON TABLE core.feature_flags IS 'Interruptor de funcionalidad del sistema, con su estado, quién lo activó y metadatos de control.';
COMMENT ON TABLE core.flujo_definicion IS 'Paso del flujo operativo por tipo de trámite —caso o reporte—, con su orden, estado resultante y rol responsable.';
COMMENT ON TABLE core.flujo_estado IS 'Catálogo de estados posibles de un paso del flujo operativo, con su color y marca de estado final.';
COMMENT ON TABLE core.fuentes_evidencia IS 'Fuente que respalda un hecho de la cronología, con su tipo, su referencia y su nivel de confiabilidad.';
COMMENT ON TABLE core.hitos_compromiso IS 'Hito de avance de un compromiso, con su fecha de vencimiento, estado, fecha real y evidencia de cumplimiento.';
COMMENT ON TABLE core.hitos_compromiso_estado_historico IS 'Corte histórico del estado de un hito de compromiso, con la observación y la fecha en que se registró.';
COMMENT ON TABLE core.integraciones IS 'Intercambio configurado con un sistema externo, con su origen, destino, tipo de sincronización y estado.';
COMMENT ON TABLE core.locales IS 'Local disponible para reuniones y capacitaciones, con su dirección, aforo, equipamiento y datos de contacto.';
COMMENT ON TABLE core.log_accesos IS 'Intento de acceso al sistema con el documento presentado, el rol declarado y el resultado obtenido.';
COMMENT ON TABLE core.mesa_miembros IS 'Miembro de una mesa de diálogo, con su rol, el documento de designación y el período de vigencia.';
COMMENT ON TABLE core.mesas_dialogo IS 'Espacio de diálogo formalizado, con su tipo de instrumento, base legal, vigencia, objetivo y rol del sector.';
COMMENT ON TABLE core.migracion_conflicto IS 'Conflicto detectado al cargar los datos del sistema anterior, con su hoja y fila de origen y el estado de resolución.';
COMMENT ON TABLE core.notificaciones IS 'Aviso dirigido a un usuario sobre un hecho del sistema, con su tipo, vencimiento y estado de lectura.';
COMMENT ON TABLE core.organizaciones IS 'Organización inscrita como actor colectivo, con su RUC, base legal, integrantes y situación ante el registro de OSPA.';
COMMENT ON TABLE core.outbox_integracion IS 'Cola de envíos hacia un sistema externo, con el contenido transformado, los reintentos y la aprobación previa.';
COMMENT ON TABLE core.output_contracts IS 'Contrato de cada salida generada, con su formato, la consulta que la originó y el commit y snapshot que la respaldan.';
COMMENT ON TABLE core.permiso_aprobacion IS 'Autorización temporal que habilita a un usuario a aprobar un objeto determinado, con su vigencia y quién la otorgó. Desde el parche 22 tiene consumidor: core.puede_aprobar() la consulta para la suplencia del aprobador y core.vw_permiso_aprobacion la expone a la pantalla de administración. Una fila aquí no concede un rol: solo habilita a esa persona para ese objeto mientras la vigencia esté abierta. Vacía significa que no hay suplencia designada';
COMMENT ON TABLE core.plan_acciones IS 'Acción de un plan de intervención, con su responsable, plazo, criterio de contención y estado de avance.';
COMMENT ON TABLE core.planes_accion IS 'Plan de acción con su monto presupuestal, plazo límite y estado de aprobación, asociado a un documento del expediente.';
COMMENT ON TABLE core.proceso_instancia IS 'Paso ejecutado del flujo operativo sobre un caso o un reporte, con su estado, responsable y fechas de ocurrencia.';
COMMENT ON TABLE core.provincias IS 'Provincia con su código de ubigeo y su región, para desagregar casos y lugares en el territorio.';
COMMENT ON TABLE core.query_cache IS 'Respuesta memorizada de una consulta, con su clave, su clasificación máxima y la huella de la política vigente al generarla.';
COMMENT ON TABLE core.regiones IS 'Región o departamento con su ubigeo, unidad de mayor nivel para la desagregación territorial de casos y usuarios.';
COMMENT ON TABLE core.reunion_participantes IS 'Participante de una reunión de diálogo, con su institución, cargo y constancia de asistencia.';
COMMENT ON TABLE core.reuniones_dialogo IS 'Reunión de diálogo vinculada a un caso, con su tipo, fecha, lugar y unidad orgánica que la convoca.';
COMMENT ON TABLE core.riesgo_social_ordinal IS 'Nivel de riesgo social estimado para un lugar y una fecha, con el conteo de eventos y convocatorias y su justificación.';
COMMENT ON TABLE core.roles IS 'Rol de acceso del sistema con su nivel máximo de clasificación, base del control de permisos por perfil.';
COMMENT ON TABLE core.suscripcion_notificacion IS 'Suscripción de una unidad orgánica a los avisos de alerta, clima social y reporte rápido, con su canal preferido.';
COMMENT ON TABLE core.usuario_roles IS 'Asignación de un rol a un usuario, con el período durante el cual esa asignación está vigente.';
COMMENT ON TABLE core.usuario_territorio IS 'Regiones sobre las que puede consultar un usuario, como restricción territorial de su acceso.';
COMMENT ON TABLE core.usuarios IS 'Persona habilitada para operar el sistema, con su unidad orgánica, cargo, credenciales e identificación de directorio.';
COMMENT ON TABLE ctx.captura IS 'Captura de una fuente web o documento durante una recolección, con su hash, archivo, tipo de contenido y clasificación.';
COMMENT ON TABLE ctx.cat_dominios IS 'Catálogo de dominios de contexto —oceanográfico, económico, territorial, hídrico, entre otros— que agrupan variables.';
COMMENT ON TABLE ctx.cat_fuentes IS 'Catálogo de fuentes de las que se obtienen variables de contexto, con su nombre y su dirección base.';
COMMENT ON TABLE ctx.cat_variables IS 'Catálogo de variables de contexto con su dominio, unidad de medida, ámbito, periodicidad y plazo de frescura.';
COMMENT ON TABLE ctx.herramienta IS 'Herramienta de recolección con su tipo, dominios permitidos, límite de uso por hora y si exige aprobación previa.';
COMMENT ON TABLE ctx.observaciones IS 'Valor observado de una variable de contexto en una fecha y ámbito, con su fuente y su desagregación territorial.';
COMMENT ON TABLE ctx.snapshot IS 'Foto del contexto vigente de un caso en una fecha, con su hash, que respalda lo que el sistema sabía en ese momento.';
COMMENT ON TABLE ctx.trabajo_recoleccion IS 'Trabajo programado de recolección de una variable o indicador, con su herramienta, estado y último error registrado.';
COMMENT ON TABLE ctx.variable_fuentes IS 'Fuente admisible para obtener una variable de contexto, como vínculo entre la variable y la fuente que la publica.';
COMMENT ON TABLE ctx.zonas_maritimas IS 'Zona marítima de referencia para desagregar las observaciones de contexto de ámbito marino.';
COMMENT ON TABLE domain.artefacto IS 'Artefacto de dominio versionado y bitemporal, con su carga útil, su sujeto, su estado de validación y su clasificación.';
COMMENT ON TABLE domain.cat_estados_artefacto IS 'Catálogo de estados del ciclo de vida de un artefacto: borrador, pendiente de validación, validado, aprobado o cerrado.';
COMMENT ON TABLE domain.regla_negocio IS 'Regla que condiciona el paso de un artefacto entre estados, con su condición de evaluación y su mensaje de error.';
COMMENT ON TABLE domain.tipo_artefacto IS 'Tipo de artefacto con su dominio, esquema de validación y requisitos de sujeto, que habilita nuevas entidades sin cambiar el modelo.';
COMMENT ON TABLE economic.anexo_metodologico IS 'Anexo que documenta la cadena causal, las fuentes y los supuestos de una medición económica, con su aprobación formal.';
COMMENT ON TABLE economic.counterfactual_analysis IS 'Estimación contrafactual de un caso resuelto: costo sin intervención, costo con intervención y diferencia, contrastada con casos análogos.';
COMMENT ON TABLE economic.impact_scenarios IS 'Escenario de impacto económico de un caso, con sus supuestos, pérdida estimada y efecto fiscal y laboral.';
COMMENT ON TABLE forecast.model_drift_log IS 'Registro de degradación detectada en un modelo de pronóstico, con su tipo, su magnitud y la acción adoptada.';
COMMENT ON TABLE forecast.model_registry IS 'Registro de modelos de pronóstico con su versión, sus datos de entrenamiento, sus métricas y su estado de vigencia.';
COMMENT ON TABLE forecast.predictions IS 'Pronóstico emitido por un modelo sobre un objetivo, con su probabilidad, su intervalo de confianza y su horizonte.';
COMMENT ON TABLE impact.analisis_recurrencia IS 'Verificación de si un caso resuelto volvió a abrirse en 12, 24 o 36 meses, con el caso recurrente identificado.';
COMMENT ON TABLE impact.encuestas_post_resolucion IS 'Encuesta aplicada a un actor tras la resolución de un caso, sobre satisfacción, confianza institucional y percepción del resultado.';
COMMENT ON TABLE impact.evaluaciones_efectividad IS 'Evaluación de la eficacia de un tipo de intervención sobre un tipo de caso, medida por resolución sin recurrencia en un período.';
COMMENT ON TABLE impact.indicadores_bienestar IS 'Indicador de bienestar del actor tras la intervención: ingreso, empleo formal, servicios básicos y seguridad alimentaria.';
COMMENT ON TABLE impact.lecciones_aprendidas_automaticas IS 'Lección extraída automáticamente de un caso resuelto, con su tipo, la evidencia que la sustenta y la revisión del equipo.';
COMMENT ON TABLE ind.brecha IS 'Brecha de información que impide calcular un indicador, con su propuesta de recolección, su esfuerzo estimado en horas y la decisión adoptada.';
COMMENT ON TABLE ind.indicador IS 'Indicador del marco de seguimiento, con su definición, naturaleza, dirección deseada y anexo de la Guía que lo origina.';
COMMENT ON TABLE ind.plantilla IS 'Plantilla de documento que define qué indicadores debe contener un producto, con su tipo de documento y su descripción.';
COMMENT ON TABLE ind.plantilla_slot IS 'Casillero de una plantilla que reserva un lugar para un indicador determinado, con su orden de aparición.';
COMMENT ON TABLE ind.proxy_justificacion IS 'Justificación metodológica de una variante usada como aproximación, con sus supuestos, límites e incertidumbre declarada.';
COMMENT ON TABLE ind.relacion_dependencia IS 'Dependencia entre dos indicadores o entre un indicador y una variable de contexto, con su tipo y su peso.';
COMMENT ON TABLE ind.resultado IS 'Valor calculado de una variante de indicador por distrito y período, con su cobertura, su denominador y su incertidumbre.';
COMMENT ON TABLE ind.seleccion IS 'Elección de la variante de indicador usada en un caso o distrito y período, con las alternativas evaluadas y el motivo.';
COMMENT ON TABLE ind.variante IS 'Forma concreta de calcular un indicador —factible, proxy o censal— con su especificación y su nivel de evidencia.';
COMMENT ON TABLE kag.actor_name_history IS 'Nombre sucesivo de un actor con su período de vigencia y su fuente, para distinguir un cambio de denominación de un cambio de identidad.';
COMMENT ON TABLE kag.actor_profile IS 'Perfil narrativo del actor —resumen y formas de trabajo— redactado a partir del material documental reunido sobre él.';
COMMENT ON TABLE kag.actor_profile_attribute IS 'Atributo del perfil de un actor, versionado y con evidencia, como capacidad, interés o repertorio de acción.';
COMMENT ON TABLE kag.anomalia_contextual IS 'Anomalía de un caso frente a su contexto sistémico, con la explicación que la acompaña y su estado de revisión.';
COMMENT ON TABLE kag.arista_evidencia IS 'Fragmento documental que respalda una arista del grafo, con la cita textual y su nivel de confianza.';
COMMENT ON TABLE kag.aristas IS 'Relación entre dos nodos del grafo —alianza, tensión, influencia, posición o causalidad— con su justificación y su vigencia.';
COMMENT ON TABLE kag.atributo_evidencia IS 'Fragmento que respalda un atributo del perfil de un actor, con la cita textual y su nivel de confianza.';
COMMENT ON TABLE kag.cat_clases_arista IS 'Catálogo de clases de relación del grafo: relación, influencia, posición, participación, causal y discurso.';
COMMENT ON TABLE kag.cat_corpus IS 'Catálogo de corpus documentales: campo, normativa, literatura, metodología, medios o dato oficial.';
COMMENT ON TABLE kag.cat_tipos_arista IS 'Catálogo de tipos de relación del grafo, con su clase, si es dirigida y los tipos de nodo que conecta.';
COMMENT ON TABLE kag.cat_tipos_nodo IS 'Catálogo de tipos de nodo admitidos: actor, caso, demanda, solución, lugar, concepto, hipótesis y otros.';
COMMENT ON TABLE kag.comunidad IS 'Comunidad detectada en una corrida del grafo, con su número, su nivel jerárquico y la comunidad de la que depende.';
COMMENT ON TABLE kag.comunidad_corrida IS 'Ejecución del algoritmo de comunidades, con su momento de validez, resolución, semilla y número de aristas consideradas.';
COMMENT ON TABLE kag.comunidad_miembro IS 'Nodo que integra una comunidad del grafo, como vínculo entre la comunidad y el elemento que la compone.';
COMMENT ON TABLE kag.comunidad_resumen IS 'Resumen redactado de una comunidad del grafo, con el modelo y la versión que lo produjeron y su validación humana.';
COMMENT ON TABLE kag.contraste IS 'Contraste entre dos afirmaciones de fuentes distintas, con la escala de cada una, el tipo de discrepancia y su explicación.';
COMMENT ON TABLE kag.documento_fragmento IS 'Fragmento de un documento fuente, con su posición, su rango de caracteres y la versión del texto de la que proviene.';
COMMENT ON TABLE kag.documento_fuente IS 'Documento incorporado al grafo con su título, tipo, hash del contenido y versión del texto, base de toda cita textual.';
COMMENT ON TABLE kag.embedding IS 'Vector de un fragmento o de un atributo, con el modelo y la versión que lo generaron, para la búsqueda semántica.';
COMMENT ON TABLE kag.entity_merge_log IS 'Fusión de identidades de actores en una sola, con su justificación, el responsable y la posibilidad de reversión.';
COMMENT ON TABLE kag.entity_merge_members IS 'Actor que participó en una fusión de identidades, con el rol que tuvo como origen o como resultante.';
COMMENT ON TABLE kag.hipotesis IS 'Hipótesis de trabajo sobre un caso, con su enunciado, su origen, su estado y su nivel de confianza.';
COMMENT ON TABLE kag.hipotesis_en_salida IS 'Hipótesis citada en una salida del sistema, con el rótulo con que se presentó al lector del reporte.';
COMMENT ON TABLE kag.hipotesis_evidencia IS 'Fragmento que sostiene o refuta una hipótesis de trabajo, con el sentido en que la afecta.';
COMMENT ON TABLE kag.metrica_nodo IS 'Medida calculada de un nodo del grafo en un período, como centralidad o grado, con marca de criticidad.';
COMMENT ON TABLE kag.nodos IS 'Vértice del grafo de conocimiento; hoy solo proyecta actores, con el identificador y la etiqueta del sujeto representado.';
COMMENT ON TABLE kag.objetivo IS 'Objetivo que persigue un actor en el marco de un caso, con su tipo y su período de vigencia.';
COMMENT ON TABLE kag.saturacion IS 'Iteración de análisis que registra cuántas afirmaciones nuevas aportó y si con ello cambió la comprensión del caso.';
COMMENT ON TABLE kag.vacio_informacion IS 'Vacío de información identificado, vinculado a un indicador o a una brecha, con su propuesta de cierre y su estado.';
COMMENT ON TABLE kag.validacion_hallazgo IS 'Calificación de un hallazgo del análisis con su nivel de confianza y la justificación de quien lo validó.';
COMMENT ON TABLE lex.clase IS 'Clase de discurso obtenida en una corrida de análisis léxico, con su porcentaje de unidades de contexto clasificadas.';
COMMENT ON TABLE lex.clase_termino IS 'Término asociado a una clase de discurso, con su chi cuadrado, sus frecuencias y su significación estadística.';
COMMENT ON TABLE lex.coocurrencia IS 'Coocurrencia de dos términos en un corpus, con su valor y la medida estadística usada para calcularla.';
COMMENT ON TABLE lex.corpus IS 'Conjunto congelado de documentos sobre el que se mide el lenguaje, con su filtro, su hash y su clasificación máxima.';
COMMENT ON TABLE lex.corpus_documento IS 'Documento incluido en un corpus léxico, con su versión de texto y las variables que lo describen, como caso o fecha.';
COMMENT ON TABLE lex.corrida IS 'Ejecución de un método léxico —frecuencias, coocurrencia, clasificación o diccionario— con su software, parámetros y métricas.';
COMMENT ON TABLE lex.diccionario IS 'Diccionario temático versionado, con su descripción y su autor, usado para medir categorías en el discurso.';
COMMENT ON TABLE lex.diccionario_entrada IS 'Entrada de un diccionario léxico: un lema o una expresión regular, con su tipo y su categoría temática.';
COMMENT ON TABLE lex.serie IS 'Frecuencia normalizada de un término por período y ámbito, comparada con una ventana de referencia configurable.';
COMMENT ON TABLE lex.termino IS 'Lema del vocabulario de análisis, con su categoría gramatical e idioma, reutilizable entre distintos corpus.';
COMMENT ON TABLE lex.uce IS 'Unidad de contexto elemental del corpus, delimitada por posiciones en el texto y marcada como retenida o descartada.';
COMMENT ON TABLE model.model_card IS 'Ficha de un modelo con su propósito, variables de entrada y salida, parámetros, métricas, limitaciones y revisión programada.';
COMMENT ON TABLE mype.ejecucion_nec IS 'Adjudicación y pago de un núcleo ejecutor de compras a una MYPE, con montos, hitos de entrega, conformidad y mora.';
COMMENT ON TABLE pesca.licencia_cites_denp IS 'Permiso CITES de exportación solicitado y dictaminado, con la especie, los volúmenes y las fechas del trámite.';
COMMENT ON TABLE pesca.trazabilidad_qr IS 'Escaneo de un código QR de trazabilidad de una licencia, con su etapa, el lugar de desembarque y su validez.';
COMMENT ON TABLE policy.cat_tipos_regla IS 'Catálogo de tipos de regla de política, con las claves que cada tipo exige en sus parámetros y su esquema.';
COMMENT ON TABLE policy.escenario IS 'Escenario que agrupa un conjunto de reglas de política para simular o evaluar el efecto de una decisión.';
COMMENT ON TABLE policy.escenario_regla IS 'Regla que compone un escenario de política, como vínculo entre el escenario y la norma que lo integra.';
COMMENT ON TABLE policy.gobierno IS 'Período de gobierno con su fecha de inicio y de término, que enmarca la vigencia de cargos y reglas.';
COMMENT ON TABLE policy.regla IS 'Regla de política vigente —norma, restricción o preferencia— con su texto, parámetros, alcance, fuente y aprobación.';
COMMENT ON TABLE policy.snapshot IS 'Foto del conjunto de reglas vigente en un momento, con su hash, que permite reconstruir qué política se aplicó.';
COMMENT ON TABLE policy.snapshot_regla IS 'Regla incluida en una foto del ordenamiento, como vínculo entre el snapshot y la norma que quedó congelada.';
COMMENT ON TABLE policy.titular IS 'Persona que ocupa un cargo de gobierno durante un período, con su nombre y sus fechas de ejercicio.';
COMMENT ON TABLE proteccion.registro_parametrico IS 'Cobertura de un programa de protección a un actor afectado, con su umbral, monto máximo y período de cobertura.';
COMMENT ON TABLE qda.codigo IS 'Código del libro de códigos, con su jerarquía, su identificador externo y la marca de si admite codificación.';
COMMENT ON TABLE qda.exportacion IS 'Registro de cada salida de material cualitativo fuera del perímetro, con su hash, su autorización y su caducidad.';
COMMENT ON TABLE qda.fuente IS 'Texto exportado a un software de análisis cualitativo, con su versión, su hash y su longitud, base de los segmentos.';
COMMENT ON TABLE qda.libro_codigos IS 'Libro de códigos versionado de un proyecto cualitativo, con su origen y su período de vigencia.';
COMMENT ON TABLE qda.mapeo_pseudonimo IS 'Equivalencia entre el token usado en una exportación y el actor real, guardada para poder revertir la pseudonimización.';
COMMENT ON TABLE qda.memo IS 'Nota analítica asociada a un elemento del proyecto cualitativo, con su ámbito y el autor que la redactó.';
COMMENT ON TABLE qda.perdida_roundtrip IS 'Elemento que no sobrevive al viaje de ida y vuelta entre el sistema y el software cualitativo, con su causa documentada.';
COMMENT ON TABLE qda.proyecto IS 'Proyecto cualitativo importado desde un software de análisis, con su versión del estándar, su archivo y su hash.';
COMMENT ON TABLE qda.segmento IS 'Tramo de texto codificado con un código, delimitado por posiciones de caracteres y con vigencia bitemporal.';
COMMENT ON TABLE qda.segmento_fragmento IS 'Solape entre un segmento codificado y un fragmento del grafo, con el número de caracteres que comparten.';
COMMENT ON TABLE ref.base_legal_evidencia IS 'Fragmento del banco de conocimiento que respalda una base legal, con su página, su similitud y la confianza de la correspondencia, para poder citar la fuente exacta.';
COMMENT ON TABLE ref.base_legal_tratamiento IS 'Base legal que autoriza el tratamiento de datos personales —norma, artículo, finalidad y condiciones—, ligada al banco de datos que la invoca.';
COMMENT ON TABLE staging.lote IS 'Lote de carga manual de archivos externos, con su punto de ingesta, su hash, su estado y su validación.';
COMMENT ON TABLE staging.registro IS 'Fila de un lote de aterrizaje temporal, con su carga útil y los errores de validación que se le detectaron.';
COMMENT ON TABLE territorio.anomalias_ais IS 'Anomalía detectada en el seguimiento satelital de embarcaciones, con su zona, su tipo y su severidad.';
COMMENT ON TABLE territorio.caleta_detalle IS 'Datos propios de una caleta de pescadores artesanales, con su tipo y su nivel de organización.';
COMMENT ON TABLE territorio.cat_tipos_lugar IS 'Catálogo de tipos de lugar: terminal pesquero, desembarcadero, planta, caleta, CITE, estación hídrica o piscigranja.';
COMMENT ON TABLE territorio.certificaciones_planta IS 'Certificación sanitaria o ambiental de una planta procesadora, con su estado y su fecha de vigencia.';
COMMENT ON TABLE territorio.cuadricula_sismica IS 'Cuadrícula de un lote sísmico con su operador, fase y período, para cruzar actividad extractiva con territorio.';
COMMENT ON TABLE territorio.desembarcadero_detalle IS 'Datos del desembarcadero artesanal, con el número de embarcaciones registradas que operan en él.';
COMMENT ON TABLE territorio.estacion_hidrica_detalle IS 'Estación de monitoreo hídrico con su código de la autoridad del agua, su cuenca, subcuenca y altitud.';
COMMENT ON TABLE territorio.expansion_informal IS 'Detección de expansión informal en un lugar, con su área, la precisión del método y su validación humana.';
COMMENT ON TABLE territorio.impacto_conflicto_planta IS 'Evaluación del impacto de un caso sobre una planta, con las certificaciones en riesgo y el nivel estimado.';
COMMENT ON TABLE territorio.lugar_actores IS 'Actor vinculado a un lugar del territorio, con el tipo de vínculo y su período de vigencia.';
COMMENT ON TABLE territorio.lugares IS 'Punto del territorio —caleta, planta, puerto o estación— con su tipo, coordenadas, distrito y estado operativo.';
COMMENT ON TABLE territorio.parque_industrial IS 'Parque industrial con su polígono, hectáreas totales, útiles, saneadas y su estado de saneamiento.';
COMMENT ON TABLE territorio.patrones_seguridad_caleta IS 'Patrón de seguridad observado en una caleta durante un período, con su tipo, su severidad y su fuente.';
COMMENT ON TABLE territorio.planta_detalle IS 'Datos de una planta procesadora: razón social, tipo de procesamiento, capacidad instalada y empleo directo.';
COMMENT ON TABLE territorio.terminal_detalle IS 'Datos propios del terminal pesquero, con su capacidad de procesamiento diario expresada en toneladas.';
COMMENT ON TABLE territorio.zona_pesca IS 'Zona de pesca delimitada por un polígono, con su tipo, su especie asociada y su período de vigencia.';

-- ---- Descripcion de cada columna ----------------------------

COMMENT ON COLUMN agent.cat_detalle_schema.agente IS 'Agente cuyo detalle de corrida valida este esquema JSON versionado';
COMMENT ON COLUMN agent.cat_detalle_schema.esquema_json IS 'Definición JSON que fija qué campos admite el detalle de la corrida';
COMMENT ON COLUMN agent.cat_detalle_schema.version IS 'Versión del esquema JSON que fija la estructura del detalle de una corrida';
COMMENT ON COLUMN agent.cat_detalle_schema.vigente_desde IS 'Fecha desde la que rige esta versión del esquema de detalle';
COMMENT ON COLUMN agent.feedback_log.agente IS 'Agente cuya salida fue corregida por el revisor';
COMMENT ON COLUMN agent.feedback_log.correccion_humano IS 'Versión corregida por la persona que reemplaza la salida del agente';
COMMENT ON COLUMN agent.feedback_log.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.feedback_log.input_ref IS 'Referencia al insumo que recibió el agente antes de producir la salida';
COMMENT ON COLUMN agent.feedback_log.justificacion IS 'Motivo que el revisor expone para respaldar la corrección aplicada';
COMMENT ON COLUMN agent.feedback_log.output_agente IS 'Salida original del agente que el revisor evaluó y corrigió';
COMMENT ON COLUMN agent.feedback_log.revisado_por IS 'Usuario que emitió la corrección y respalda la revisión de la salida';
COMMENT ON COLUMN agent.feedback_log.ts IS 'Momento en que se emitió la corrección humana sobre la salida del agente';
COMMENT ON COLUMN agent.lessons_learned.activo IS 'Indica si la lección ya se incorporó a las plantillas del agente';
COMMENT ON COLUMN agent.lessons_learned.agente_destino IS 'Agente al que se aplicará la lección en sus próximas plantillas';
COMMENT ON COLUMN agent.lessons_learned.aprobado_por IS 'Usuario que aprobó la incorporación de la lección a las plantillas';
COMMENT ON COLUMN agent.lessons_learned.created_at IS 'Momento en que se creó el registro';
COMMENT ON COLUMN agent.lessons_learned.ejemplo_json IS 'Ejemplo concreto del error, guardado en JSON para ilustrar el patrón';
COMMENT ON COLUMN agent.lessons_learned.feedback_id IS 'Corrección humana de la que se deriva esta lección';
COMMENT ON COLUMN agent.lessons_learned.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.lessons_learned.patron IS 'Descripción del patrón de error que la lección busca evitar en adelante';
COMMENT ON COLUMN agent.lessons_learned.tipo_error IS 'Categoría del error detectado que originó la lección aprendida';
COMMENT ON COLUMN agent.llm_call.destino IS 'Destino de ejecución indicado con un código corto, según dónde corre el modelo';
COMMENT ON COLUMN agent.llm_call.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.llm_call.latencia_ms IS 'Tiempo de respuesta de la llamada al modelo, medido en milisegundos';
COMMENT ON COLUMN agent.llm_call.modelo IS 'Nombre del modelo de lenguaje invocado en esta llamada';
COMMENT ON COLUMN agent.llm_call.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';
COMMENT ON COLUMN agent.llm_call.policy_snapshot_id IS 'Instantánea de política vigente en la llamada, que fija sus reglas y límites';
COMMENT ON COLUMN agent.llm_call.prompt_hash IS 'Huella del prompt enviado, para detectar cambios sin guardar el texto completo';
COMMENT ON COLUMN agent.llm_call.run_id IS 'Ejecución del agente a la que pertenece la llamada, para agrupar su costo y su latencia';
COMMENT ON COLUMN agent.llm_call.temperatura IS 'Temperatura usada al generar la respuesta, que fija su grado de variabilidad';
COMMENT ON COLUMN agent.llm_call.tokens_in IS 'Cantidad de tokens consumidos por el prompt enviado al modelo';
COMMENT ON COLUMN agent.llm_call.tokens_out IS 'Cantidad de tokens producidos por el modelo en su respuesta';
COMMENT ON COLUMN agent.llm_call.ts IS 'Momento en que se hizo la llamada al modelo, parte de su clave de partición';
COMMENT ON COLUMN agent.llm_call.veredicto_guardrails IS 'Resultado de los filtros de seguridad aplicados al prompt y a la respuesta';
COMMENT ON COLUMN agent.llm_call.version_modelo IS 'Versión exacta del modelo que respondió, necesaria para reproducir la salida';
COMMENT ON COLUMN agent.llm_call.version_plantilla_prompt IS 'Versión de la plantilla de prompt aplicada, para rastrear el origen del texto';
COMMENT ON COLUMN agent.llm_call_fragmento.call_id IS 'Llamada al modelo que recuperó el fragmento documental';
COMMENT ON COLUMN agent.llm_call_fragmento.call_ts IS 'Momento de la llamada, que con su identificador completa la clave del vínculo';
COMMENT ON COLUMN agent.llm_call_fragmento.fragmento_id IS 'Fragmento documental recuperado como insumo de la llamada';
COMMENT ON COLUMN agent.llm_call_fragmento.rank_rrf IS 'Posición que el fragmento ocupó tras fusionar los resultados de búsqueda';
COMMENT ON COLUMN agent.llm_call_fragmento.score_rerank IS 'Puntaje del reordenamiento final del fragmento dentro de la lista recuperada';
COMMENT ON COLUMN agent.llm_call_fragmento.score_rrf IS 'Puntaje de fusión del fragmento, que pondera sus apariciones en cada búsqueda';
COMMENT ON COLUMN agent.modelo_registro.alta IS 'Fecha en que el modelo se incorporó al padrón de modelos autorizados';
COMMENT ON COLUMN agent.modelo_registro.destinos_permitidos IS 'Lista de destinos donde puede ejecutarse el modelo, en formato JSON';
COMMENT ON COLUMN agent.modelo_registro.estado IS 'Situación del modelo en el padrón, como activo o retirado';
COMMENT ON COLUMN agent.modelo_registro.hash_pesos IS 'Huella de los pesos del modelo, para verificar que no se alteraron';
COMMENT ON COLUMN agent.modelo_registro.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.modelo_registro.modelo IS 'Nombre del modelo autorizado a operar en el sistema';
COMMENT ON COLUMN agent.modelo_registro.version IS 'Versión del modelo autorizado que queda bajo control de cambios';
COMMENT ON COLUMN agent.plantilla_prompt.activo IS 'Indica si la plantilla está habilitada para generar prompts';
COMMENT ON COLUMN agent.plantilla_prompt.codigo IS 'Código corto que identifica la plantilla entre las de su mismo agente';
COMMENT ON COLUMN agent.plantilla_prompt.few_shot_json IS 'Ejemplos de entrada y salida incluidos en el prompt para guiar al agente';
COMMENT ON COLUMN agent.plantilla_prompt.hash_prompt IS 'Huella del prompt de sistema, para comprobar que la respuesta provino de él';
COMMENT ON COLUMN agent.plantilla_prompt.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.plantilla_prompt.output_schema_id IS 'Identificador del esquema que debe cumplir la salida esperada del agente';
COMMENT ON COLUMN agent.plantilla_prompt.supersedes_id IS 'Versión anterior de la plantilla que esta reemplaza';
COMMENT ON COLUMN agent.plantilla_prompt.system_prompt IS 'Texto del prompt de sistema que orienta el comportamiento del agente';
COMMENT ON COLUMN agent.plantilla_prompt.version IS 'Versión de la plantilla, que permite comparar lo generado con cada una';
COMMENT ON COLUMN agent.plantilla_prompt.vigente_desde IS 'Momento desde el que la plantilla puede usarse en producción';
COMMENT ON COLUMN agent.plantilla_prompt.vigente_hasta IS 'Momento en que la plantilla deja de usarse, vacío mientras siga vigente';
COMMENT ON COLUMN agent.run_log.agente IS 'Agente que tomó la decisión consignada en la bitácora';
COMMENT ON COLUMN agent.run_log.confidence IS 'Grado de certeza del dato, entre 0 y 1';
COMMENT ON COLUMN agent.run_log.decision IS 'Tipo de decisión adoptada por el agente para atender la consulta';
COMMENT ON COLUMN agent.run_log.detalle IS 'Detalle de la decisión en JSON, con los datos que la sustentan';
COMMENT ON COLUMN agent.run_log.detalle_schema_version IS 'Versión del esquema JSON que estructura el detalle de la decisión';
COMMENT ON COLUMN agent.run_log.hash IS 'Hash de esta entrada, que sella su contenido y encadena la siguiente';
COMMENT ON COLUMN agent.run_log.id IS 'Identificador interno de la fila';
COMMENT ON COLUMN agent.run_log.input_hash IS 'Huella de los insumos usados por el agente, para verificar su integridad';
